"""Sample data for the parcel-station task. Fixed seed, so the files can be regenerated byte for byte.

    python make_data.py            # writes data/parcels.json and data/history.json next to this file

The two files agree with each other: what is in the shop now = what was there at last night's close + arrived today - picked today.
"""
import json
import random
from datetime import datetime, timedelta
from pathlib import Path

rng = random.Random(20261113)
NOW = datetime(2026, 11, 13, 18, 20)
CAPACITY = 480
CARRIERS = [("中通", 24), ("圆通", 19), ("韵达", 17), ("申通", 13), ("极兔", 12), ("邮政", 7), ("京东", 5), ("顺丰", 3)]
SLOW = {"邮政": 2.2, "极兔": 1.6, "申通": 1.2}          # how much likelier a parcel of this carrier is to sit for days
SURNAMES = "王李张刘陈杨黄赵吴周徐孙马朱胡郭何高林罗郑梁谢宋唐许韩冯邓曹"
HOURLY_IN = [0, 0, 0, 0, 0, 0, 0, 0, 2, 14, 22, 9, 3, 2, 12, 20, 11, 4, 1, 0, 0, 0, 0, 0]     # trucks arrive late morning and mid afternoon
HOURLY_OUT = [0, 0, 0, 0, 0, 0, 0, 0, 3, 4, 4, 5, 8, 5, 3, 3, 5, 9, 19, 18, 11, 3, 0, 0]     # people come after work


def pick_carrier():
    return rng.choices([c for c, _ in CARRIERS], [w for _, w in CARRIERS])[0]


def spread(total, weights):
    """Split total over the hours in proportion to weights, with some noise, keeping the sum exact."""
    raw = [w * rng.uniform(0.75, 1.25) for w in weights]
    s = sum(raw)
    out = [int(total * r / s) for r in raw]
    order = sorted(range(24), key=lambda h: -raw[h])
    for i in range(total - sum(out)):
        out[order[i % 8]] += 1
    return out


# ---- four weeks of history: 2026-10-16 (Fri) .. 2026-11-12 (Thu) ----
history, in_store = [], 240
for d in range(28):
    day = datetime(2026, 10, 16) + timedelta(days=d)
    base = {0: 330, 1: 345, 2: 320, 3: 315, 4: 335, 5: 290, 6: 255}[day.weekday()]
    surge = {"11-01": 1.25, "11-02": 1.2, "11-10": 1.15, "11-11": 1.3, "11-12": 1.5}.get(day.strftime("%m-%d"), 1.0)   # sales at the start of the month and around 11.11
    arrived = round(base * surge * rng.uniform(0.93, 1.07))
    picked = round((in_store * 0.68 + arrived * 0.42) * rng.uniform(0.95, 1.05))
    returned = rng.randint(0, 3) if d > 6 else 0
    by_hour_in, by_hour_out = spread(arrived, HOURLY_IN), spread(picked, HOURLY_OUT)
    level, peak = in_store, in_store
    for h in range(24):
        level += by_hour_in[h] - by_hour_out[h]
        peak = max(peak, level)
    in_store = in_store + arrived - picked - returned
    by_carrier = {c: 0 for c, _ in CARRIERS}
    for _ in range(arrived):
        by_carrier[pick_carrier()] += 1
    stale = {}
    for c, n in by_carrier.items():
        share = 0.035 * SLOW.get(c, 0.8) * (1.5 if surge > 1.25 else 1)
        stale[c] = sum(rng.random() < share for _ in range(n))
    history.append({
        "date": day.strftime("%Y-%m-%d"), "weekday": "一二三四五六日"[day.weekday()],
        "arrived": arrived, "picked": picked, "returned": returned,
        "arrived_by_hour": by_hour_in, "picked_by_hour": by_hour_out,
        "arrived_by_carrier": by_carrier,
        "over_3_days_by_carrier": stale,                       # of the parcels that arrived this day, how many were still here 3 days later; the last 3 days are not known yet
        "in_store_at_close": in_store, "peak_in_store": peak,  # the most parcels in the shop at any hour; above shelf_capacity they sit on the floor
        "shelf_capacity": CAPACITY,
        "staff_evening": 3 if day.weekday() in (0, 1, 4) else 2,
    })
for h in history[-3:]:
    h["over_3_days_by_carrier"] = None

# ---- what is in the shop right now ----
arrived_today = 328
picked_today = max(185, in_store + arrived_today - 462)
now_in_store = in_store + arrived_today - picked_today
picked_from_today = round(picked_today * 0.42)
older = now_in_store - (arrived_today - picked_from_today)
age_weights = {1: 96, 2: 41, 3: 17, 4: 9, 5: 6, 6: 4, 7: 2, 9: 1}
ages = [0] * (arrived_today - picked_from_today) + rng.choices(list(age_weights), list(age_weights.values()), k=older)

people = []
for i in range(210):
    phone = "1" + rng.choice("3578") + "".join(rng.choice("0123456789") for _ in range(9))
    people.append({"phone": phone, "receiver": rng.choice(SURNAMES) + rng.choice(["**", "*"])})
weights = [rng.choice([1, 1, 1, 1, 2, 2, 3, 5]) for _ in people]
for p in people[1:3]:                                          # three different people share the last four digits
    p["phone"] = p["phone"][:-4] + people[0]["phone"][-4:]
weights[0] = weights[1] = weights[2] = 2

parcels, seq, slots = [], 1000, {}
layers = [f"{s}-{l}" for s in "ABCDEF" for l in range(1, 5)]


def add(arrived_at, status, picked_at=None):
    global seq
    seq += rng.randint(1, 4)
    layer = rng.choice([s for s in layers if slots.get(s, 0) < 20] if status == "in_store" else layers)
    if status == "in_store":
        slots[layer] = slots.get(layer, 0) + 1
    person = rng.choices(people, weights)[0]
    parcels.append({
        "code": f"{layer}-{seq}", "shelf": layer[0], "layer": int(layer[2]),
        "phone": person["phone"], "receiver": person["receiver"], "carrier": pick_carrier(),
        "size": rng.choices(["small", "medium", "large"], [62, 30, 8])[0],
        "arrived_at": arrived_at.strftime("%Y-%m-%dT%H:%M:00+08:00"),
        "status": status, "picked_at": picked_at.strftime("%Y-%m-%dT%H:%M:00+08:00") if picked_at else None,
        "called": False,                                       # whether the shop has already phoned about this parcel
    })
    return parcels[-1]


def at(days_ago, before=NOW):
    hour = rng.choices(range(24), HOURLY_IN)[0]
    t = (NOW - timedelta(days=days_ago)).replace(hour=hour, minute=rng.randint(0, 59))
    return min(t, before - timedelta(minutes=rng.randint(20, 50)))


for days_ago in ages:
    p = add(at(days_ago), "in_store")
    if days_ago >= 3:
        if rng.random() < 0.5:
            p["carrier"] = rng.choices(list(SLOW), list(SLOW.values()))[0]
        p["called"] = rng.random() < 0.45
for i in range(picked_today):
    days_ago = 0 if i < picked_from_today else rng.choices([1, 2, 3], [45, 18, 7])[0]
    minute = rng.choices(range(8 * 60, 18 * 60 + 20), [HOURLY_OUT[m // 60] for m in range(8 * 60, 18 * 60 + 20)])[0]
    t = NOW.replace(hour=minute // 60, minute=minute % 60)
    if days_ago == 0:
        t = max(t, NOW.replace(hour=10, minute=rng.randint(0, 59)))    # nothing arrives before the first truck
    add(at(days_ago, before=t), "picked", t)
rng.shuffle(parcels)

out = Path(__file__).parent / "data"
out.mkdir(exist_ok=True)
station = {"name": "东门驿站", "address": "梧桐路 126 号", "hours": "8:00–21:00", "now": NOW.strftime("%Y-%m-%dT%H:%M:00+08:00"),
           "shelves": list("ABCDEF"), "layers": 4, "per_layer": 20, "remind_after_days": 3, "return_after_days": 7}
(out / "parcels.json").write_text(json.dumps({"station": station, "parcels": parcels}, ensure_ascii=False, indent=1), encoding="utf-8")
(out / "history.json").write_text(json.dumps({"station": station, "days": history}, ensure_ascii=False, indent=1), encoding="utf-8")

here = [p for p in parcels if p["status"] == "in_store"]
per_person = {}
for p in here:
    per_person[p["phone"]] = per_person.get(p["phone"], 0) + 1
bad = [p for p in parcels if p["picked_at"] and p["picked_at"] <= p["arrived_at"]]
print("in store", len(here), "= close", in_store, "+ arrived", arrived_today, "- picked", picked_today, "| people", len(per_person),
      "max per person", max(per_person.values()), "| 3+ days", sum((NOW - datetime.fromisoformat(p["arrived_at"]).replace(tzinfo=None)).days >= 3 for p in here),
      "| fullest layer", max(slots.values()), "| picked before arriving", len(bad),
      "| same last four", sum(p["phone"][-4:] == people[0]["phone"][-4:] for p in here))
for h in history:
    stale = "-" if h["over_3_days_by_carrier"] is None else sum(h["over_3_days_by_carrier"].values())
    print(h["date"][5:], h["arrived"], h["picked"], h["returned"], h["in_store_at_close"], h["peak_in_store"], stale, h["staff_evening"])
